import React, { useState, useEffect } from 'react';

const testimonials = [
    {
        id: 1,
        name: "Dr. Sarah Matthew",
        role: "Alumni, Class of 2010",
        quote: "CEC provided me with the foundational knowledge and practical skills that I use every day in my career. The faculty's dedication to student success is simply unmatched.",
        image: "https://i.pravatar.cc/150?img=1"
    },
    {
        id: 2,
        name: "Rahul R.",
        role: "Current Student, S6 CSE",
        quote: "The coding culture here is fantastic. With round-the-clock lab facilities and immensely supportive peers, I've been able to hone my skills and secure a top placement.",
        image: "https://i.pravatar.cc/150?img=11"
    },
    {
        id: 3,
        name: "Prof. Anila James",
        role: "HOD, Electronics",
        quote: "We don't just teach the syllabus. We focus on innovation and research. It's a privilege to mentor such brilliant minds year after year.",
        image: "https://i.pravatar.cc/150?img=5"
    }
];

const Testimonial = () => {
    const [currentIndex, setCurrentIndex] = useState(0);

    useEffect(() => {
        const timer = setInterval(() => {
            setCurrentIndex((prev) => (prev + 1) % testimonials.length);
        }, 5000);
        return () => clearInterval(timer);
    }, []);

    return (
        <section id="testimonials" className="py-16 bg-cream/50 dark:bg-slate-900 border-t border-border/30 dark:border-slate-800 transition-colors duration-300">
            <div className="max-w-6xl mx-auto px-4 lg:px-6">
                <div className="mb-12 text-center">
                    <h2 className="text-[2.25rem] font-display font-bold text-slate-800 dark:text-gray-100 mb-4 uppercase tracking-wide">
                        Voices of CEC
                    </h2>
                    <p className="text-lg text-slate-600 dark:text-gray-400 font-medium">
                        Hear from our students, alumni, and faculty.
                    </p>
                </div>

                <div className="relative">
                    <div className="overflow-hidden">
                        <div 
                            className="flex transition-transform duration-500 ease-in-out"
                            style={{ transform: `translateX(-${currentIndex * 100}%)` }}
                        >
                            {testimonials.map((t) => (
                                <div key={t.id} className="w-full flex-shrink-0 px-4 flex justify-center py-6">
                                    <div className="max-w-3xl w-full bg-white dark:bg-slate-800 rounded-[20px] shadow-[0_8px_30px_rgba(10,22,40,0.04)] dark:shadow-none dark:border dark:border-slate-700 p-8 md:p-12 text-center relative mt-6">
                                        <div className="absolute top-0 left-1/2 -translate-x-1/2 -translate-y-1/2">
                                            <img src={t.image} alt={t.name} className="w-24 h-24 rounded-full border-4 border-white dark:border-slate-800 shadow-md object-cover" />
                                        </div>
                                        <div className="mt-8">
                                            <p className="text-xl md:text-2xl italic text-slate-700 dark:text-gray-300 leading-relaxed font-display">
                                                "{t.quote}"
                                            </p>
                                            <div className="mt-8">
                                                <h4 className="font-bold text-lg text-coral dark:text-coral2">{t.name}</h4>
                                                <p className="text-sm font-bold text-slate-500 dark:text-gray-400 tracking-wider uppercase mt-1">{t.role}</p>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>

                    <div className="flex justify-center mt-6 gap-2">
                        {testimonials.map((_, idx) => (
                            <button
                                key={idx}
                                onClick={() => setCurrentIndex(idx)}
                                className={`h-[6px] rounded-full transition-all duration-300 ${currentIndex === idx ? 'w-8 bg-coral dark:bg-coral2' : 'w-3 bg-slate-200 dark:bg-slate-700 hover:bg-slate-300 dark:hover:bg-slate-600'}`}
                                aria-label={`Go to testimonial ${idx + 1}`}
                            />
                        ))}
                    </div>
                </div>
            </div>
        </section>
    );
};

export default Testimonial;
